contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount, uint minVal, uint collectAm) public payable {
        require(address(this).balance >= amount);
        c.SetMinSum(minVal);
        c.SetLogFile(address(this));
        c.Initialized();
        c.Put{value: amount}(lockTime);

        uint balBefore = address(c).balance;
        uint accBalBefore = _balanceOf(address(this));

        bool reverted;
        try c.Collect(collectAm) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint accBalAfter = _balanceOf(address(this));
        uint balAfter = address(c).balance;

        bool shouldRevert = (accBalBefore < minVal) || (accBalBefore < collectAm) || (block.timestamp <= _unlockTimeOf(address(this)));
        assert(reverted == shouldRevert);
        if (!reverted) {
            assert(accBalAfter == accBalBefore - collectAm);
            assert(balAfter == balBefore - collectAm);
        }
    }

    function _balanceOf(address a) internal view returns (uint) {
        (uint unlock, uint bal) = c.Acc(a);
        unlock;
        return bal;
    }

    function _unlockTimeOf(address a) internal view returns (uint) {
        (uint unlock, uint bal) = c.Acc(a);
        bal;
        return unlock;
    }

    receive() external payable {}
}

