contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint lockTime, uint amount, uint minVal, uint collectAm) public payable {
        // Bound lockTime so that block.timestamp + lockTime cannot overflow in Put.
        require(lockTime < 2**200);
        require(amount <= address(this).balance);

        c.SetMinSum(minVal);
        c.SetLogFile(address(this));
        c.Initialized();
        c.Put{value: amount}(lockTime);

        (uint unlockTimeBefore, uint balanceBefore) = c.Acc(address(this));
        uint cBalanceBefore = address(c).balance;

        bool shouldSucceed = (balanceBefore >= minVal) && (collectAm <= balanceBefore) && (block.timestamp > unlockTimeBefore);

        bool reverted;
        try c.Collect{value: 0}(collectAm) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (, uint balanceAfter) = c.Acc(address(this));
        uint cBalanceAfter = address(c).balance;

        if (shouldSucceed) {
            assert(!reverted);
            assert(balanceAfter + collectAm == balanceBefore);
            assert(cBalanceAfter + collectAm == cBalanceBefore);
        } else {
            assert(reverted);
            assert(balanceAfter == balanceBefore);
            assert(cBalanceAfter == cBalanceBefore);
        }
    }
