        // The rule: the call must succeed, the balance must increase exactly by amount,
        // and the unlockTime must be at least block.timestamp + _lockTime (or stay higher).
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));

        assert(!reverted
            && afterBalance == beforeBalance + amount
            && afterUnlock >= beforeUnlock
            && afterUnlock >= beforeTs + _lockTime);
    }

    receive() external payable {}
}

