contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint _minSum, address _log, uint _lockTime, uint _am) public payable {
        require(address(this).balance >= 0);
        require(_lockTime <= 1000000000);
        require(_am <= 1000000000);

        // Initialize the contract so that Collect can proceed past the condition checks.
        c.SetMinSum(_minSum);
        c.SetLogFile(_log);
        c.Initialized();

        // Fund the caller's account so the balance and min-sum checks can pass when _am <= _minSum.
        c.Put{value: _am + 1}(_lockTime);

        // Read the observable state before the deciding call.
        uint beforeBalance = address(c).balance;
        bool reverted;

        // The deciding call: Collect with amount _am will attempt to call msg.sender and then
        // call LogFile.AddMessage. Because the test contract has no payable fallback that accepts
        // Ether, the low-level call {value: _am} fails, so the state-changing branch is taken only
        // for the balance/log update when the call would succeed. We use a try/catch to observe
        // whether Collect reverts.
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: after a successful (non-reverting) Collect, the contract's Ether balance
        // must have decreased by exactly _am because Collect sends _am to msg.sender.
        // If Collect reverted, no Ether may have left the contract.
        if (!reverted) {
            assert(address(c).balance + _am == beforeBalance);
        } else {
            assert(address(c).balance == beforeBalance);
        }
    }

    receive() external payable {}
}

