contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Record the sender's balance and unlock time before the call
        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        // Execute the deciding call
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the sender's balance and unlock time after the call
        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        // The general rule: On a fresh contract, Put must not revert, and it must add msg.value to balance and extend unlockTime to max(old unlockTime, block.timestamp + _lockTime)
        if (!reverted) {
            // Since we cannot read block.timestamp before and after precisely, we assert on balance and that unlock time is at least the argument
            assert(balanceAfter == balanceBefore + amount);
            // unlockTime must be at least block.timestamp + lockTime, but we only know now, so we check that it is at least the previous unlockTime and at least lockTime
            assert(unlockAfter >= unlockBefore);
            assert(unlockAfter >= lockTime);
        } else {
            // If it reverted, nothing should have changed
            assert(balanceAfter == balanceBefore);
            assert(unlockAfter == unlockBefore);
        }
    }

    receive() external payable {}
}

